 uint64_t k=0,n=0,block_start=0,block_count=0,weight_row=0,weight_rows=0,row_stride=0,expert_stride=0,weight_offset=0,weight_bytes=0,output_row=0,output_rows=0;
 uint32_t input=0,q8=0,weights=0,control=0,cpu=0,pre=0,post=0;bool immutable=true;
